      try c.encode(body, forKey: AnyKey("body"))
    case .unsnooze(let body):
      try c.encode("unsnooze", forKey: AnyKey("action"))
      try c.encode(body, forKey: AnyKey("body"))
    }
  }
}

/// Source: docs/local-first.md "The outbox": what became of a command
public enum Outcome: Codable, Sendable, Equatable {
  /// 2xx: the head's card replaces the device's
  case sent(card: MeCard)
  /// 409: decided or replaced elsewhere; the head's state wins
  case conflict(card: MeCard, message: String?)
  /// 403 reauthentication_required: the row waits for the passkey
  case needsPerson
  /// Any other 4xx: the row is dropped
  case refused(status: Int, message: String)
  /// Not sent yet (offline, or behind a row that waits): the card stays settled on the device
  case waiting

  public init(from decoder: any Decoder) throws {
    let c = try decoder.container(keyedBy: AnyKey.self)
    let tag = try c.decode(String.self, forKey: AnyKey("kind"))
    switch tag {
    case "sent": self = .sent(card: try c.decode(MeCard.self, forKey: AnyKey("card")))
    case "conflict": self = .conflict(card: try c.decode(MeCard.self, forKey: AnyKey("card")), message: try c.decodeIfPresent(String.self, forKey: AnyKey("message")))
    case "needs-person": self = .needsPerson
    case "refused": self = .refused(status: try c.decode(Int.self, forKey: AnyKey("status")), message: try c.decode(String.self, forKey: AnyKey("message")))
    case "waiting": self = .waiting
    default: throw DecodingError.dataCorruptedError(forKey: AnyKey("kind"), in: c, debugDescription: "unknown kind \(tag)")
    }
  }

  public func encode(to encoder: any Encoder) throws {
    var c = encoder.container(keyedBy: AnyKey.self)
    switch self {
    case .sent(let card):
      try c.encode("sent", forKey: AnyKey("kind"))
      try c.encode(card, forKey: AnyKey("card"))
    case .conflict(let card, let message):
      try c.encode("conflict", forKey: AnyKey("kind"))
      try c.encode(card, forKey: AnyKey("card"))
      try c.encodeIfPresent(message, forKey: AnyKey("message"))
    case .needsPerson:
      try c.encode("needs-person", forKey: AnyKey("kind"))
    case .refused(let status, let message):
      try c.encode("refused", forKey: AnyKey("kind"))
      try c.encode(status, forKey: AnyKey("status"))
      try c.encode(message, forKey: AnyKey("message"))
    case .waiting:
      try c.encode("waiting", forKey: AnyKey("kind"))
    }
  }
}
